                        let bench=roster(teams[side]).filter{!$0.isPitcher && $0.available(day) && !usedHitters.contains($0.profile.id) && $0.fits(position)}
                        if let sub=bench.max(by:{$0.value-$0.fatigue*0.25<$1.value-$1.fatigue*0.25}),random()<0.22,
